int twice_half(int n) {
    return n * 2 / 2;
}

int main(void) {
    printf("%d\n", twice_half(3.7));
}

int sum(int n) {
    if (n == 0) return 0;
    return n + sum(n - 1);
}

int count_down(int n) {
    if (n == 0) return 0;
    return 1 + count_down(n - 1);
}

